package com.samanramezani1377.woogit.data.repository

import com.samanramezani1377.woogit.core.domain.entity.EntityId
import com.samanramezani1377.woogit.core.domain.entity.StoreId
import com.samanramezani1377.woogit.core.domain.error.CoreResult
import com.samanramezani1377.woogit.core.domain.model.*
import com.samanramezani1377.woogit.core.domain.repository.*
import com.samanramezani1377.woogit.data.network.*
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import java.security.MessageDigest

private val mutationJson = Json { ignoreUnknownKeys = true; explicitNulls = false }
private fun payloadHash(value:String)=MessageDigest.getInstance("SHA-256").digest(value.toByteArray()).joinToString(""){ "%02x".format(it) }
@Serializable private data class ProductMutation(val name:String,val sku:String?=null,val description:String?=null,val short_description:String?=null,val status:String,val type:String,val regular_price:String?=null,val sale_price:String?=null,val images:List<WooImageTypedDto> = emptyList(),val attributes:List<WooProductAttributeDto> = emptyList())
private fun WooProductTypedDto.toDomain()=Product(EntityId(id.toString()),name,sku,description,short_description,when(status){"publish"->ProductStatus.PUBLISHED;"pending"->ProductStatus.PENDING;"private"->ProductStatus.PRIVATE;else->ProductStatus.DRAFT},when(type){"grouped"->ProductType.GROUPED;"external"->ProductType.EXTERNAL;"variable"->ProductType.VARIABLE;else->ProductType.SIMPLE},Pricing(regular_price,sale_price,on_sale),Stock(stock_quantity,when(stock_status){"outofstock"->StockStatus.OUT_OF_STOCK;"onbackorder"->StockStatus.ON_BACKORDER;else->StockStatus.IN_STOCK},manage_stock),images.map{ProductImage(it.id?.let(::EntityId)?:EntityId("0"),it.src,it.name,it.alt)},categories.map{IdName(EntityId(it.id.toString()),it.name)},attributes.map{Attribute(it.id?.let(::EntityId),it.name,it.visible,it.variation,it.options)},date_modified_gmt)

class ProductRepositoryV1Impl(private val local:LocalProductDataSource<Product>,private val provider:WooCommerceClientProvider,private val coordinator:MutationCoordinator):ProductRepository{
 override suspend fun get(storeId:StoreId,id:EntityId)=provider.client(storeId).fold({(store,api)->api.product(store.baseUrl,id.value.toLong()).fold({remote->remote.toDomain().also{local.upsert(storeId,it)}.let(CoreResult::Success)},{local.get(storeId,id)})},{local.get(storeId,id)})
 override suspend fun list(storeId:StoreId,page:Int,perPage:Int,search:String?):CoreResult<List<Product>>{val cached=if(page==1)local.list(storeId)else null;return provider.client(storeId).fold({(store,api)->api.products(store.baseUrl,page,perPage,search).fold({values->val d=values.map(WooProductTypedDto::toDomain);d.forEach{local.upsert(storeId,it)};CoreResult.Success(d)},{cached?:CoreResult.Failure(DomainErrorMapper.map(it))})},{cached?:CoreResult.Failure(DomainErrorMapper.map(it))})}
 private fun mutation(product:Product)=mutationJson.encodeToString(ProductMutation(product.name,product.sku,product.description,product.shortDescription,product.status.name.lowercase(),product.type.name.lowercase(),product.pricing.regular,product.pricing.sale,product.images.map{WooImageTypedDto(it.id?.value?.toLongOrNull(),it.src,it.name,it.alt)},product.attributes.map{WooProductAttributeDto(it.id?.value?.toLongOrNull(),it.name,it.visible,it.variation,it.options)}))
 override suspend fun create(storeId:StoreId,product:Product):CoreResult<Product>{val payload=mutation(product);val hash=payloadHash(payload);val op=PendingOperation(EntityId("product-create-${storeId.value}-${hash.take(20)}"),storeId,"product",product.id,OperationType.CREATE,payload,hash,0,null);val localResult=coordinator.execute(op){local.upsert(storeId,product).let{if(it is CoreResult.Success)CoreResult.Success(product)else CoreResult.Failure((it as CoreResult.Failure).error)}};if(localResult is CoreResult.Failure)return localResult;return provider.client(storeId).fold({(store,api)->api.createProduct(store.baseUrl,WooProductTypedDto(0,product.name,sku=product.sku,description=product.description,short_description=product.shortDescription,status=product.status.name.lowercase(),type=product.type.name.lowercase(),regular_price=product.pricing.regular,sale_price=product.pricing.sale,images=product.images.map{WooImageTypedDto(it.id?.value?.toLongOrNull(),it.src,it.name,it.alt)},attributes=product.attributes.map{WooProductAttributeDto(it.id?.value?.toLongOrNull(),it.name,it.visible,it.variation,it.options)})).fold({remote->val d=remote.toDomain();local.upsert(storeId,d);CoreResult.Success(d)},{if(it is HttpApiException&&it.statusCode in 408..599)CoreResult.Success(product)else CoreResult.Failure(DomainErrorMapper.map(it))})},{CoreResult.Success(product)})}
 override suspend fun update(storeId:StoreId,id:EntityId,product:Product):CoreResult<Product>{val payload=mutation(product);val hash=payloadHash(payload);val op=PendingOperation(EntityId("product-update-${storeId.value}-${id.value}-${hash.take(16)}"),storeId,"product",id,OperationType.UPDATE,payload,hash,0,null);val localResult=coordinator.execute(op){local.upsert(storeId,product).let{if(it is CoreResult.Success)CoreResult.Success(product)else CoreResult.Failure((it as CoreResult.Failure).error)}};if(localResult is CoreResult.Failure)return localResult;return provider.client(storeId).fold({(store,api)->api.updateProduct(store.baseUrl,id.value.toLong(),WooProductTypedDto(id.value.toLong(),product.name,sku=product.sku,description=product.description,short_description=product.shortDescription,status=product.status.name.lowercase(),type=product.type.name.lowercase(),regular_price=product.pricing.regular,sale_price=product.pricing.sale,images=product.images.map{WooImageTypedDto(it.id?.value?.toLongOrNull(),it.src,it.name,it.alt)},attributes=product.attributes.map{WooProductAttributeDto(it.id?.value?.toLongOrNull(),it.name,it.visible,it.variation,it.options)})).fold({remote->val d=remote.toDomain();local.upsert(storeId,d);CoreResult.Success(d)},{if(it is HttpApiException&&it.statusCode in 408..599)CoreResult.Success(product)else CoreResult.Failure(DomainErrorMapper.map(it))})},{CoreResult.Success(product)})}
 override suspend fun delete(storeId:StoreId,id:EntityId):CoreResult<Unit>{val payload="{}";val hash=payloadHash(payload);val op=PendingOperation(EntityId("product-delete-${storeId.value}-${id.value}-${hash.take(16)}"),storeId,"product",id,OperationType.DELETE,payload,hash,0,null);val localResult=coordinator.execute(op){local.delete(storeId,id)};if(localResult is CoreResult.Failure)return localResult;return provider.client(storeId).fold({(store,api)->api.deleteProduct(store.baseUrl,id.value.toLong()).fold({CoreResult.Success(Unit)},{if(it is HttpApiException&&it.statusCode in 408..599)CoreResult.Success(Unit)else CoreResult.Failure(DomainErrorMapper.map(it))})},{CoreResult.Success(Unit)})}
}
private object DomainErrorMapper{fun map(error:Throwable)=when(error){is HttpApiException->when(error.statusCode){401->com.samanramezani1377.woogit.core.domain.error.DomainError.Authentication("Authentication failed");403->com.samanramezani1377.woogit.core.domain.error.DomainError.Permission("Permission denied");404->com.samanramezani1377.woogit.core.domain.error.DomainError.NotFound("remote",error.statusCode.toString());409->com.samanramezani1377.woogit.core.domain.error.DomainError.Conflict("Remote conflict");422->com.samanramezani1377.woogit.core.domain.error.DomainError.Validation("Validation failed");429->com.samanramezani1377.woogit.core.domain.error.DomainError.RateLimited("Rate limited");in 500..599->com.samanramezani1377.woogit.core.domain.error.DomainError.Server("Server error");else->com.samanramezani1377.woogit.core.domain.error.DomainError.Unknown("HTTP ${error.statusCode}")};else->com.samanramezani1377.woogit.core.domain.error.DomainError.Network(error.message?:"Network failure")}}
